import { GoogleGenAI, Type, Schema } from "@google/genai";
import { Flower } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const flowerSchema: Schema = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      rank: { type: Type.INTEGER },
      name: { type: Type.STRING },
      englishName: { type: Type.STRING, description: "Scientific or common English name of the flower for image generation" },
      plantingPeriod: { type: Type.STRING, description: "When to sow seeds or plant seedlings" },
      bloomingPeriod: { type: Type.STRING, description: "When the flower blooms" },
      characteristics: { type: Type.STRING, description: "Key features of the flower" },
      caution: { type: Type.STRING, description: "Care instructions or warnings" },
      relatedFlowers: {
        type: Type.ARRAY,
        items: { type: Type.STRING },
        description: "5 specific varieties of this flower ranked by popularity"
      },
    },
    required: ["rank", "name", "englishName", "plantingPeriod", "bloomingPeriod", "characteristics", "caution", "relatedFlowers"],
  },
};

export const getFlowerRecommendations = async (userQuery?: string): Promise<Flower[]> => {
  const date = new Date();
  const currentMonth = date.toLocaleString('ko-KR', { month: 'long' });

  // Logic to interpret "지금" (now) as the specific current month
  let context = userQuery;
  if (!context || context.trim() === '지금') {
    context = currentMonth;
  }

  const prompt = `
    사용자 입력: "${context}"

    당신은 한국의 가드닝 전문가 AI입니다. 
    사용자의 입력이 '특정 꽃 이름'인지 아니면 '시기, 계절, 장소'인지 판단하여 아래 규칙에 따라 10개의 꽃 추천 리스트를 JSON으로 작성하세요.

    [판단 로직 및 생성 규칙]

    CASE 1: 사용자가 "특정 꽃 이름"을 입력한 경우 (예: 수국, 튤립, 장미 등)
    1. **Rank 1**: 무조건 사용자가 입력한 바로 그 꽃에 대한 정보를 작성하세요.
    2. **Rank 2~10**: 입력한 꽃과 함께 심기 좋은 '동반 식물(Companion Plants)' 또는 비슷한 시기에 심거나 피는 꽃, 혹은 식물학적으로 유사한 꽃들을 추천하세요.
    3. 이 경우 'plantingPeriod'는 해당 꽃을 한국에서 심기에 가장 적합한 시기를 정확히 기재하세요.

    CASE 2: 사용자가 "시기(월), 계절, 장소"를 입력한 경우 (예: 8월, 가을, 베란다, 그늘 등)
    1. 해당 시기나 환경에 **씨앗을 심거나(파종) 모종을 심기에(식재)** 가장 적합하고 인기 있는 꽃 10가지를 추천하세요.
    2. (중요) 사용자가 입력한 월은 '꽃이 피는 시기'가 아니라 **'심는 시기'**를 의미합니다. (예: "12월" 입력 시 -> 12월에 심어야 하는 구근이나 실내 파종 꽃 추천)

    [공통 작성 상세 가이드]
    1. 언어: 한국어
    2. 기후 기준: 한국 기후
    3. 데이터 필드 설명:
       - name: 꽃 이름 (한글)
       - englishName: 이미지 생성을 위한 정확한 영문명
       - plantingPeriod: 파종 또는 모종 식재 시기 (구체적인 월 표시)
       - bloomingPeriod: 개화 시기
       - characteristics: 매력적인 특징 1~2문장
       - caution: 키울 때 주의할 점
       - relatedFlowers: 해당 꽃의 가장 인기 있는 세부 품종 5가지를 인기순으로 나열 (예: 수국 -> ["아나벨수국", "목수국", "산수국", ...])

    응답은 반드시 JSON 형식이어야 합니다.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: flowerSchema,
        temperature: 0.4, 
      },
    });

    const text = response.text;
    if (!text) {
      throw new Error("No response from Gemini");
    }

    const data = JSON.parse(text) as Flower[];
    // Ensure strict ranking order
    return data.sort((a, b) => a.rank - b.rank);

  } catch (error) {
    console.error("Error fetching flower data:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import LandingPage from './components/LandingPage';
import FlowerCard from './components/FlowerCard';
import { getFlowerRecommendations } from './services/geminiService';
import { Flower, ViewState } from './types';
import { Loader2, RefreshCw, Leaf, X } from 'lucide-react';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('LANDING');
  const [flowers, setFlowers] = useState<Flower[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [currentQuery, setCurrentQuery] = useState<string>('');

  const handleStart = async (query: string = '') => {
    let formattedQuery = query.trim();

    // If the input is just numbers (1 or 2 digits), treat it as a month (e.g., "7" -> "7월")
    if (/^\d{1,2}$/.test(formattedQuery)) {
      formattedQuery = `${formattedQuery}월`;
    }

    setView('LOADING');
    setError(null);
    setCurrentQuery(formattedQuery);

    try {
      const data = await getFlowerRecommendations(formattedQuery);
      setFlowers(data);
      setView('RESULTS');
    } catch (err) {
      console.error(err);
      setError("죄송합니다. 꽃 정보를 불러오는데 실패했습니다. 잠시 후 다시 시도해주세요.");
      setView('ERROR');
    }
  };

  const handleReset = () => {
    setView('LANDING');
    setFlowers([]);
    setCurrentQuery('');
  };

  const handleRetry = () => {
    handleStart(currentQuery);
  };

  return (
    <div className="min-h-screen bg-stone-50 font-sans text-stone-900 selection:bg-emerald-200">
      {view === 'LANDING' && (
        <LandingPage onStart={handleStart} />
      )}

      {view === 'LOADING' && (
        <div className="flex flex-col items-center justify-center min-h-screen text-center px-4">
          <div className="relative">
            <div className="absolute inset-0 bg-emerald-300 rounded-full blur-xl opacity-20 animate-pulse"></div>
            <Loader2 className="w-16 h-16 text-emerald-600 animate-spin relative z-10" />
          </div>
          <h2 className="mt-8 text-2xl font-serif text-stone-800">
            {currentQuery ? `"${currentQuery}"에 적합한` : '이번 달'} 꽃을 찾고 있습니다...
          </h2>
          <p className="mt-2 text-stone-500">잠시만 기다려주세요.</p>
        </div>
      )}

      {view === 'ERROR' && (
        <div className="flex flex-col items-center justify-center min-h-screen px-4 text-center">
          <div className="w-16 h-16 bg-red-50 rounded-full flex items-center justify-center mb-6">
            <Leaf className="w-8 h-8 text-red-400 rotate-180" />
          </div>
          <h2 className="text-2xl font-bold text-stone-800 mb-2">문제가 발생했습니다</h2>
          <p className="text-stone-500 mb-8 max-w-md">{error}</p>
          <button 
            onClick={handleRetry}
            className="px-6 py-3 bg-stone-900 text-white rounded-lg hover:bg-stone-800 transition-colors flex items-center gap-2"
          >
            <RefreshCw size={18} /> 다시 시도하기
          </button>
        </div>
      )}

      {view === 'RESULTS' && (
        <div className="min-h-screen bg-stone-50">
          <header className="sticky top-0 z-50 bg-white/80 backdrop-blur-md border-b border-stone-100">
            <div className="max-w-5xl mx-auto px-6 py-4 flex items-center justify-between">
              <div 
                className="flex items-center gap-2" 
              >
                <Leaf className="text-emerald-600" />
                <span className="font-serif text-xl font-bold">뭐 심지?</span>
              </div>

              <div className="flex items-center gap-4">
                <button 
                  onClick={handleRetry}
                  className="text-sm font-medium text-stone-500 hover:text-emerald-600 transition-colors flex items-center gap-1"
                  title="결과 다시 생성"
                >
                  <RefreshCw size={16} /> <span className="hidden sm:inline">새로고침</span>
                </button>
                <div className="w-px h-4 bg-stone-300 mx-1"></div>
                <button 
                  onClick={handleReset}
                  className="p-2 -mr-2 text-stone-400 hover:text-stone-900 hover:bg-stone-100 rounded-full transition-all"
                  aria-label="종료하고 처음으로 돌아가기"
                  title="종료"
                >
                  <X size={24} />
                </button>
              </div>
            </div>
          </header>

          <main className="max-w-5xl mx-auto px-6 py-12">
            <div className="mb-12 text-center">
              <span className="text-emerald-600 font-semibold tracking-wider text-sm uppercase">Curated List</span>
              <h2 className="text-4xl font-serif text-stone-900 mt-3 mb-4">
                {currentQuery ? `${currentQuery} 추천 꽃 TOP 10` : '이달의 추천 꽃 TOP 10'}
              </h2>
              <p className="text-stone-500">
                선택하신 시기와 환경에 가장 적합한 식물들을 엄선했습니다. <br/>
                카드를 눌러 상세 정보를 확인해보세요.
              </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-fade-in-up">
              {flowers.map((flower) => (
                <FlowerCard key={flower.rank} flower={flower} />
              ))}
            </div>

            <div className="mt-16 text-center pb-8">
              <p className="text-stone-400 text-sm">
                * 추천 순위는 계절 적합성과 재배 난이도를 고려하여 AI가 선정했습니다.
              </p>
            </div>
          </main>
        </div>
      )}
    </div>
  );
};

